export type Callback = (payload: any) => void;

export class EventBus {
  private subs: Map<string, Set<Callback>> = new Map();

  subscribe(event: string, cb: Callback): void {
    if (!this.subs.has(event)) this.subs.set(event, new Set());
    this.subs.get(event)!.add(cb);
  }

  publish(event: string, payload: any): void {
    const set = this.subs.get(event);
    if (!set) return;
    for (const cb of Array.from(set)) {
      try {
        cb(payload);
      } catch (err) {
        // swallow errors to avoid breaking publisher
        // in real system we'd log
      }
    }
  }
}

import { randomUUID } from 'crypto';

export interface User {
  id: string;
  name: string;
  email: string;
}

export class UserService {
  private store: Map<string, User> = new Map();

  create(data: { name: string; email: string }): User {
    const user: User = { id: randomUUID(), name: data.name, email: data.email };
    this.store.set(user.id, user);
    return user;
  }

  getById(id: string): User | null {
    return this.store.get(id) ?? null;
  }

  getAll(): User[] {
    return Array.from(this.store.values());
  }

  update(id: string, data: Partial<Omit<User, 'id'>>): User | null {
    const existing = this.store.get(id);
    if (!existing) return null;
    const updated = { ...existing, ...data };
    this.store.set(id, updated);
    return updated;
  }

  delete(id: string): boolean {
    return this.store.delete(id);
  }
}

import { randomUUID } from 'crypto';

export interface Project {
  id: string;
  name: string;
  description: string;
  memberIds: string[];
}

export class ProjectService {
  private store: Map<string, Project> = new Map();

  create(data: { name: string; description?: string; memberIds?: string[] }): Project {
    const project: Project = {
      id: randomUUID(),
      name: data.name,
      description: data.description ?? '',
      memberIds: data.memberIds ?? [],
    };
    this.store.set(project.id, project);
    return project;
  }

  getById(id: string): Project | null {
    return this.store.get(id) ?? null;
  }

  getAll(): Project[] {
    return Array.from(this.store.values());
  }

  update(id: string, data: Partial<Omit<Project, 'id'>>): Project | null {
    const existing = this.store.get(id);
    if (!existing) return null;
    const updated = { ...existing, ...data };
    this.store.set(id, updated);
    return updated;
  }

  delete(id: string): boolean {
    return this.store.delete(id);
  }

  addMember(projectId: string, userId: string): boolean {
    const p = this.store.get(projectId);
    if (!p) return false;
    if (!p.memberIds.includes(userId)) p.memberIds.push(userId);
    return true;
  }

  removeMember(projectId: string, userId: string): boolean {
    const p = this.store.get(projectId);
    if (!p) return false;
    p.memberIds = p.memberIds.filter((id) => id !== userId);
    this.store.set(projectId, p);
    return true;
  }
}

import { randomUUID } from 'crypto';
import { EventBus } from '../event-bus';

export type TaskStatus = 'todo' | 'in-progress' | 'done';

export interface Task {
  id: string;
  title: string;
  description: string;
  status: TaskStatus;
  assigneeId: string | null;
  projectId: string;
}

export class TaskService {
  private store: Map<string, Task> = new Map();
  constructor(private eventBus: EventBus) {}

  create(data: { title: string; description?: string; projectId: string; assigneeId?: string | null }): Task {
    const task: Task = {
      id: randomUUID(),
      title: data.title,
      description: data.description ?? '',
      status: 'todo',
      assigneeId: data.assigneeId ?? null,
      projectId: data.projectId,
    };
    this.store.set(task.id, task);
    if (task.assigneeId) {
      this.eventBus.publish('task.assigned', { taskId: task.id, taskTitle: task.title, assigneeId: task.assigneeId });
    }
    return task;
  }

  getById(id: string): Task | null {
    return this.store.get(id) ?? null;
  }

  getByProject(projectId: string): Task[] {
    return Array.from(this.store.values()).filter((t) => t.projectId === projectId);
  }

  update(id: string, data: Partial<Omit<Task, 'id' | 'projectId'>>): Task | null {
    const existing = this.store.get(id);
    if (!existing) return null;
    const updated = { ...existing, ...data };
    this.store.set(id, updated);
    return updated;
  }

  delete(id: string): boolean {
    return this.store.delete(id);
  }

  assign(id: string, assigneeId: string | null): Task | null {
    const t = this.store.get(id);
    if (!t) return null;
    t.assigneeId = assigneeId;
    this.store.set(id, t);
    this.eventBus.publish('task.assigned', { taskId: t.id, taskTitle: t.title, assigneeId });
    return t;
  }

  changeStatus(id: string, newStatus: TaskStatus): Task | null {
    const t = this.store.get(id);
    if (!t) return null;
    const order: TaskStatus[] = ['todo', 'in-progress', 'done'];
    const oldIndex = order.indexOf(t.status);
    const newIndex = order.indexOf(newStatus);
    if (newIndex === -1) return null;
    if (newIndex < oldIndex) {
      // disallow backward transitions
      return null;
    }
    if (newIndex === oldIndex) {
      // no-op
      return t;
    }
    const oldStatus = t.status;
    t.status = newStatus;
    this.store.set(id, t);
    this.eventBus.publish('task.statusChanged', { taskId: t.id, taskTitle: t.title, assigneeId: t.assigneeId, oldStatus, newStatus });
    return t;
  }
}

